#!/usr/bin/env node
// Sync the remote 9Router catalog into Pi's machine-local models.json.
// Called by the optional pi-9router-sync.service generated by pi-9router-restore.
const fs = require('fs');
const path = require('path');
const https = require('https');

const HOME = process.env.HOME || require('os').homedir();
const API_BASE_URL = 'https://rbq97ts.abc-tunnel.us/v1';
const credentialPath = path.join(HOME, '.config/ai-local/credentials/9router-remote-key');
const modelsPath = path.join(HOME, '.pi/agent/models.json');

function readJson(file, fallback) {
  try { return JSON.parse(fs.readFileSync(file, 'utf8')); } catch { return fallback; }
}

function fetchModels(apiKey) {
  return new Promise((resolve, reject) => {
    const req = https.get(`${API_BASE_URL}/models`, {
      headers: { Authorization: `Bearer ${apiKey}` }
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        if (res.statusCode && res.statusCode >= 400) {
          return reject(new Error(`Remote 9Router /v1/models returned ${res.statusCode}`));
        }
        try {
          resolve(JSON.parse(data));
        } catch (error) {
          reject(error);
        }
      });
    });
    req.on('error', reject);
  });
}

function modelMeta(id) {
  const isGemini = /gemini/i.test(id);
  return {
    id,
    ...(/gemini-2\.5-pro|gemini-3|^cx\//i.test(id) ? { reasoning: true } : {}),
    ...(isGemini ? { input: ['text', 'image'] } : {}),
    name: id.replace(/\//g, '__')
  };
}

async function main() {
  if (!fs.existsSync(credentialPath)) {
    throw new Error(`Missing remote 9Router credential: ${credentialPath}`);
  }
  const apiKey = fs.readFileSync(credentialPath, 'utf8').trim();
  if (!apiKey) {
    throw new Error(`Remote 9Router credential is empty: ${credentialPath}`);
  }

  const cfg = readJson(modelsPath, { providers: {} });
  if (!cfg.providers) cfg.providers = {};
  const existingModels = cfg.providers['9router-fantastico']?.models || [];
  const existingById = new Map(existingModels.map(model => [model.id, model]));
  const payload = await fetchModels(apiKey);
  const ids = (payload.data || []).map(model => model.id).sort();
  const models = ids.map(id => existingById.get(id) || modelMeta(id));

  cfg.providers['9router-fantastico'] = {
    baseUrl: API_BASE_URL,
    api: 'openai-completions',
    name: '9Router Fantastico',
    models
  };
  delete cfg.providers['9router'];

  fs.mkdirSync(path.dirname(modelsPath), { recursive: true });
  const tmpPath = `${modelsPath}.tmp`;
  fs.writeFileSync(tmpPath, `${JSON.stringify(cfg, null, 2)}\n`);
  fs.renameSync(tmpPath, modelsPath);
  console.log(JSON.stringify({ provider: '9router-fantastico', modelCount: models.length }, null, 2));
}

main().catch(error => {
  console.error(error.message || String(error));
  process.exit(1);
});
